{
  "assignments": [
    {
      "role": "recon_agent",
      "task": "discover_endpoints using http_probe and port_scan tools to identify all active endpoints and open ports on the target loopback address 127.0.0.1."
    },
    {
      "role": "webapp_agent",
      "task": "sql_injection_test using sql_injection_test tool to check for potential SQL injection vulnerabilities in any web applications running on the discovered endpoints."
    },
    {
      "role": "network_agent",
      "task": "service_scan using service_scan tool to gather detailed information about the services running on the open ports identified by the port_scan tool."
    },
    {
      "role": "reporting_agent",
      "task": "Synthesize evidence from the recon_agent, webapp_agent, and network_agent tasks to produce a comprehensive report on the findings."
    }
  ]
}

