{
  "assignments": [
    {
      "role": "recon_agent",
      "task": "port_scan(127.0.0.1, 1-65535, 'tcp')\nhttp_probe(127.0.0.1, 80, 'GET / HTTP/1.1')\ndiscover_endpoints(127.0.0.1, 80, 'html')\nPurpose: Identify open ports and basic HTTP endpoints for further analysis."
    },
