      "role": "webapp_agent",
      "task": "directory_traversal('/../../../../etc/passwd', 127.0.0.1, 80)\nPurpose: Test for directory traversal vulnerabilities in the web application."
    },
    {
      "role": "network_agent",
      "task": "port_scan(127.0.0.1, 1-65535, 'tcp')\nPurpose: Re-scan for any missed open ports that could be of interest."
    },
    {
      "role": "reporting_agent",
      "task": "synthesize_evidence()\nPurpose: Compile findings from reconnaissance and web application testing into a report."
    }
  ]
}

